def update(ops,data):
    if not isinstance(data,bytes)or not 1<=len(data)<=65536:raise ValueError('expected 1..65536 bytes')
    try:
        ops.begin();ops.write(data[:max(1,len(data)//3)]);
        if len(data)>1:ops.write(data[max(1,len(data)//3):]);
        ops.sync_data();ops.commit();ops.sync_directory()
    finally:ops.close()
